#include "../src/telemetry.hpp"
#include <iostream>
#include <sstream>
#include <limits>
using namespace arc;
using Microsoft::WRL::ComPtr;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
int main(int argc,char** argv){
 try{
  if(argc==2){Settings imported;require(loadSettings(std::filesystem::path(argv[1]),imported),"imported settings parse");std::cout<<"settings valid; save binding="<<imported.replay.hotModifiers<<"+"<<imported.replay.hotKey<<"\n";return 0;}
  std::cout<<"358H nominal MHz="<<nominalProcessorMhz()<<"\n";require(nominalProcessorMhz()==1900,"358H nominal base MHz");Settings original;require(original.gameEnabled,"FPS sampling enabled by default");original.alwaysAdmin=true;original.replay.enabled=true;original.monitoring=true;original.metrics[0].label=L"CPU 自定义";original.light=true;original.theme=1;original.autoGame=false;original.metrics[0].font=L"Arial";original.metrics[0].fontColor=0x123456;original.monitor.spacing=12;original.uiScale=1.25f;original.monitor.background=false;original.monitor.scale=.5f;original.monitor.opacity=0;
  original.monitor.curveWidth=680;original.monitor.columns=4;original.monitor.style=1;original.monitor.detail=static_cast<unsigned>(metricCount);original.gameMetrics[0].size=34;original.gameMetrics[0].labelSize=17;original.gameMetrics[0].labelColor=0xff1234;
  original.overlayOpen=true;original.silentStart=true;original.autoStart=true;original.monitor.cpuClock=false;original.hotModifiers=MOD_ALT;original.hotKey='M';original.manualTitle=L"我的游戏";std::wstringstream stream;writeSettings(stream,original);Settings restored;require(readSettings(stream,restored),"settings parse");require(restored.metrics[0].label==original.metrics[0].label,"Chinese roundtrip");require(restored.monitor.curveWidth==680,"curve width persistence");require(restored.monitor.columns==4&&restored.monitor.style==1&&restored.monitor.detail==metricCount&&restored.gameMetrics[0].size==34&&restored.gameMetrics[0].labelSize==17&&restored.gameMetrics[0].labelColor==0xff1234,"chart style and FPS typography roundtrip");
  require(restored.replay.enabled,"replay resume persistence");require(restored.alwaysAdmin,"administrator preference persistence");require(restored.overlayOpen&&restored.silentStart&&restored.autoStart&&!restored.monitor.cpuClock&&restored.hotModifiers==MOD_ALT&&restored.hotKey=='M'&&restored.manualTitle==L"我的游戏","startup hotkey persistence");require(packageWatts(100,100,1000000100,1000000100)==.036,"EMI units");require(!packageWatts(100,100,99,200),"energy reset rejected");require(restored.light&&restored.uiScale==1.25f&&!restored.monitor.background&&restored.monitor.scale==.5f&&restored.monitor.opacity==0,"theme scale transparency roundtrip");require(!restored.autoGame&&restored.metrics[0].fontColor==0x123456&&restored.metrics[0].font==L"Arial"&&restored.monitor.spacing==12,"appearance and focus roundtrip");
  std::wstringstream old;old<<L"ArcGlass 2\n1 1 \"Segoe UI\"\n";for(size_t i=0;i<8;++i){auto& m=original.metrics[i];old<<m.enabled<<L' '<<m.visible<<L' '<<m.graph<<L' '<<m.period<<L' '<<m.decimals<<L' '<<std::quoted(m.label)<<L'\n';}for(int i=0;i<3;++i)old<<L"\"old\" "<<(i==1?.3: .8)<<L" 20 12 24 24 1 1\n";Settings migrated;require(readSettings(old,migrated)&&std::abs(migrated.monitor.opacity-.3f)<.001f&&!migrated.light&&migrated.uiScale==1&&migrated.monitor.background,"active legacy appearance migration");
  std::wstringstream previous;previous<<L"ArcGlass 4\n1 \"Segoe UI\" 2 1\n";for(size_t i=0;i<12;++i){auto& m=original.metrics[i];previous<<m.enabled<<L' '<<m.visible<<L' '<<m.graph<<L' '<<m.period<<L' '<<m.decimals<<L' '<<std::quoted(m.label)<<L' '<<m.history<<L' '<<m.size<<L' '<<m.color<<L' '<<m.fontColor<<L' '<<m.order<<L' '<<std::quoted(m.font)<<L'\n';}previous<<L"0.8 20 12 24 24 2 1 1 1 0 0 1000 1 8\n1 10 0 1 1 1 1\n";require(readSettings(previous,migrated)&&migrated.monitor.columns==2&&migrated.autoGame==false&&migrated.metrics[0].label==original.metrics[0].label&&migrated.monitor.detail==metricCount,"v4 twelve-metric migration");
  auto file=std::filesystem::temp_directory_path()/L"ArcGlass-test.settings";require(saveSettings(file,original),"settings save");original.metrics[0].period=5000;require(saveSettings(file,original),"atomic replace");require(loadSettings(file,restored)&&restored.metrics[0].period==5000,"disk roundtrip");std::filesystem::remove(file);
  auto portable=std::filesystem::temp_directory_path()/(L"ArcReadyPanel-portable-"+std::to_wstring(GetCurrentProcessId()));std::filesystem::create_directories(portable);auto legacy=portable/L"legacy.settings";Settings imported;original.replay.bitrate=33;original.alwaysAdmin=true;require(saveSettings(legacy,original),"legacy fixture");require(loadPortableSettings(portable,legacy,imported)&&imported.replay.bitrate==33&&imported.alwaysAdmin,"portable migration and admin preflight");original.replay.bitrate=44;require(saveSettings(portableSettingsPath(portable),original),"beside executable save");require(loadPortableSettings(portable,legacy,imported)&&imported.replay.bitrate==44,"portable config wins over legacy");std::filesystem::remove(portableSettingsPath(portable));original.replay.bitrate=55;require(saveSettings(portable/L"ArcGlass.settings",original),"old portable fixture");require(loadPortableSettings(portable,legacy,imported)&&imported.replay.bitrate==55,"old portable wins over localappdata");std::filesystem::remove(portable/L"ArcGlass.settings");std::filesystem::remove(legacy);std::filesystem::remove(portable);

  std::wistringstream broken(L"ArcGlass 2 1 0");require(!readSettings(broken,restored)&&restored.metrics[0].period==5000,"transactional parse");
  original.metrics[0].period=0;original.monitor.opacity=std::numeric_limits<float>::quiet_NaN();original.sanitize();require(original.metrics[0].period==250&&std::isfinite(original.monitor.opacity),"clamp invalid config");
  LUID id{123,0};const auto token=luidToken(id);
  std::vector<CounterItem> counters={{L"pid_1_"+token+L"_phys_0_eng_0_engtype_3D",30},{L"pid_2_"+token+L"_phys_0_eng_0_engtype_3D",40},{L"pid_1_"+token+L"_phys_0_eng_1_engtype_3D",20},{L"pid_3_luid_0x00000000_0x00000456_phys_0_eng_0_engtype_3D",100},{L"pid_1_"+token+L"_phys_0_eng_2_engtype_Compute",100}};
  require(engineUsage(counters,token,L"3D")==70,"aggregate same engine, exclude other LUID/type");require(!engineUsage(counters,token,L"VideoEncode"),"missing engine unavailable");require(memoryUsage({{token+L"_phys_0",1048576}},token)==1,"memory MiB");
  require(belongs(L"pid_1_luid_0x00000000_0x0000007b_phys_0",token),"case insensitive LUID");require(!belongs(L"luid_0x00000000_0x0000007B0_phys_0",token),"LUID token boundary");
  ComPtr<IDXGIFactory1> factory;require(SUCCEEDED(CreateDXGIFactory1(IID_PPV_ARGS(&factory))),"DXGI factory");bool target=false;LUID real{};
  for(UINT i=0;;++i){ComPtr<IDXGIAdapter1> a;if(factory->EnumAdapters1(i,&a)==DXGI_ERROR_NOT_FOUND)break;DXGI_ADAPTER_DESC1 d{};a->GetDesc1(&d);if(d.VendorId==0x8086&&std::wstring(d.Description).find(L"B390")!=std::wstring::npos){real=d.AdapterLuid;target=true;break;}}
  if(!target){std::cout<<"No B390: hardware sampler test skipped\n";return 0;}
  std::wcout<<L"Target token: "<<luidToken(real)<<L'\n';
  {PdhQuery probe({L"\\GPU Engine(*)\\Utilization Percentage",L"\\GPU Adapter Memory(*)\\Shared Usage"});std::this_thread::sleep_for(std::chrono::milliseconds(1100));std::wcout<<L"PDH status: "<<probe.problem()<<L" collect="<<probe.collect()<<L'\n';for(size_t c=0;c<2;++c){auto items=probe.values(c);std::wcout<<L"counter "<<c<<L" items="<<items.size()<<L'\n';std::map<std::wstring,int> types;for(auto& item:items){auto pos=item.name.find(L"_engtype_");if(belongs(item.name,luidToken(real))&&pos!=std::wstring::npos)++types[item.name.substr(pos+9)];}for(auto& [type,count]:types)std::wcout<<L"engine type="<<type<<L" instances="<<count<<L'\n';}}
  Settings cpu;for(auto& m:cpu.metrics){m.enabled=false;m.period=250;}cpu.metrics[index(Metric::Cpu)].enabled=true;cpu.metrics[index(Metric::SelfCpu)].enabled=true;
  {Telemetry reader(cpu,real,{});std::this_thread::sleep_for(std::chrono::milliseconds(800));auto data=reader.snapshot();require(data.metrics[0].value.has_value(),"CPU sample");require(data.engineQueries==0&&data.memoryQueries==0,"disabled GPU creates no polling");require(data.metrics[index(Metric::Ram)].reads==0,"disabled RAM never read");std::cout<<"CPU sample="<<*data.metrics[0].value<<", wakes="<<data.wakes<<"\n";}
  {Settings rates;for(auto& m:rates.metrics)m.enabled=false;rates.metrics[0].enabled=true;rates.metrics[0].period=1000;rates.metrics[2].enabled=true;rates.metrics[2].period=250;Telemetry reader(rates,real,{});std::this_thread::sleep_for(std::chrono::milliseconds(1250));auto data=reader.snapshot();require(data.metrics[2].reads>=4&&data.metrics[0].reads<=2,"independent metric schedules");}
  Settings all;for(auto& m:all.metrics){m.enabled=true;m.period=1000;}all.monitoring=true;
  {Telemetry reader(all,real,{});std::this_thread::sleep_for(std::chrono::milliseconds(2400));auto data=reader.snapshot();for(size_t i=0;i<metricCount;++i){std::cout<<"metric["<<i<<"]=";if(data.metrics[i].value)std::cout<<*data.metrics[i].value;else std::cout<<"unavailable";std::cout<<" reads="<<data.metrics[i].reads<<"\n";}require(data.metrics[index(Metric::CpuPower)].value.has_value(),"native EMI package watts on 358H");require(data.engineQueries>=2&&data.memoryQueries>=2,"GPU queries run");require(data.metrics[index(Metric::Render)].value.has_value(),"target render counter");require(data.metrics[index(Metric::Shared)].value.has_value(),"target shared counter");}
  auto start=Clock::now();{Settings slow;for(auto& m:slow.metrics)m.period=10000;Telemetry reader(slow,real,{});}require(Clock::now()-start<std::chrono::seconds(1),"shutdown cancels wait");
  std::cout<<"Settings, filtering, lifecycle and real B390 telemetry passed\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}
}
